            new() { Id = 7, Name = "Chemistry", Code = "CHEM", Description = "Study of substances, their properties, and reactions." },
            new() { Id = 8, Name = "Psychology", Code = "PSYCH", Description = "Scientific study of mind, behavior, and mental processes." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
