            new() { Id = 5, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 204", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },

