            new() { Id = 7, Code = "ENGL 320", Title = "Creative Writing Workshop", Description = "Workshop-style course in fiction and poetry writing. Students produce original works, participate in peer critiques, and revise based on feedback.", Credits = 3, Schedule = "Wed 3:00–5:50 PM", Location = "Humanities 105", DepartmentId = 3, InstructorId = 3, IsFeatured = true, MaxEnrollment = 20, CurrentEnrollment = 18 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, waves, and thermodynamics. Calculus-based approach with weekly labs. Suitable for science and engineering majors.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", Location = "Physics Lab 100", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 9, Code = "PHYS 340", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, hydrogen atom, spin, and quantum entanglement.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 210", DepartmentId = 4, InstructorId = 4, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 28 },

