            new() { Id = 11, Code = "BIOL 350", Title = "Molecular Genetics", Description = "DNA replication, transcription, translation, gene regulation, and recombinant DNA technology. Lecture and laboratory components.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM + Wed Lab 9:00–11:50 AM", Location = "Life Sciences 305", DepartmentId = 5, InstructorId = 5, IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 27 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural exchanges from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Liberal Arts 202", DepartmentId = 6, InstructorId = 6, IsFeatured = false, MaxEnrollment = 75, CurrentEnrollment = 60 },
            new() { Id = 13, Code = "HIST 380", Title = "Silk Road: Trade and Culture", Description = "Examines the networks of trade, religion, and cultural exchange across Eurasia from the 2nd century BCE to the 15th century CE.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 310", DepartmentId = 6, InstructorId = 6, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },

            // Chemistry
            new() { Id = 14, Code = "CHEM 101", Title = "General Chemistry I", Description = "Atomic structure, stoichiometry, chemical bonding, states of matter, and thermochemistry. Weekly lab included.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Tue Lab 1:00–3:50 PM", Location = "Chemistry Building 100", DepartmentId = 7, InstructorId = 7, IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 78 },
            new() { Id = 15, Code = "CHEM 310", Title = "Organic Chemistry I", Description = "Structure, nomenclature, reactions, and mechanisms of carbon-containing compounds. Emphasis on stereochemistry and functional group transformations.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Chemistry Building 205", DepartmentId = 7, InstructorId = 7, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 42 },

            // Psychology
            new() { Id = 16, Code = "PSYCH 101", Title = "Introduction to Psychology", Description = "Survey of major topics in psychology: perception, cognition, learning, development, personality, social behavior, and psychological disorders.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Social Sciences 150", DepartmentId = 8, InstructorId = 8, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 17, Code = "PSYCH 320", Title = "Cognitive Psychology", Description = "In-depth exploration of attention, memory, language, problem solving, and decision-making. Includes research methods in cognitive science.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Social Sciences 220", DepartmentId = 8, InstructorId = 8, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 35 }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

