@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>Welcome to the University Course Catalog</h1>
<p class="lead">Explore our departments, discover courses, and submit your enrollment request — all in one place.</p>

<hr />

<h2>🌟 Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = CatalogService.GetDepartmentForCourse(course.Id);
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">
                        <a href="@($"courses/{course.Id}")">@course.Code: @course.Title</a>
                    </h5>
                    <span class="badge bg-primary mb-2">@dept?.Name</span>
                    <span class="badge bg-secondary mb-2">@course.Credits credits</span>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                </div>
                <div class="card-footer text-muted">
                    <small>📅 @course.Schedule</small>
                </div>
            </div>
        </div>
    }
</div>

<h2>🏛️ Departments</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-3 mb-4">
    @foreach (var dept in departments)
    {
        var courseCount = CatalogService.GetCourses().Count(c => c.DepartmentId == dept.Id);
        <div class="col">
            <div class="card h-100 border-start border-primary border-4">
                <div class="card-body">
                    <h5 class="card-title">
                        <a href="@($"courses?departmentId={dept.Id}")">@dept.Name</a>
                    </h5>
                    <p class="card-text text-muted">@dept.Description</p>
                    <span class="badge bg-info text-dark">@courseCount course(s)</span>
                </div>
            </div>
        </div>
    }
</div>

<div class="text-center mt-4 mb-3">
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-primary btn-lg">Submit Enrollment Request</a>
</div>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

