@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>
<p>Search and filter to find the right courses for you.</p>

<div class="row mb-4 g-3">
    <div class="col-md-5">
        <input type="text" class="form-control" placeholder="Search by title, code, or keyword…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <select class="form-select" @bind="selectedCredits">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted">Showing @filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    var dept = CatalogService.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td><small>@course.Schedule</small></td>
                        <td>
                            @if (spotsLeft <= 5)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-success">@spotsLeft spots left</span>
                            }
                        </td>
                        <td>
                            <a href="@($"courses/{course.Id}")" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;
    private int _selectedCredits;

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    private int selectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.SearchCourses(
            _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null,
            _selectedCredits > 0 ? _selectedCredits : null);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course Not Found</h4>
        <p>The course you're looking for doesn't exist. <a href="courses">Browse all courses</a>.</p>
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code: @course.Title</h1>
            <div class="mb-3">
                <span class="badge bg-primary fs-6">@department?.Name</span>
                <span class="badge bg-secondary fs-6">@course.Credits Credits</span>
                @{
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                }
                @if (spotsLeft <= 5)
                {
                    <span class="badge bg-warning text-dark fs-6">@spotsLeft spots remaining</span>
                }
                else
                {
                    <span class="badge bg-success fs-6">@spotsLeft spots remaining</span>
                }
            </div>

            <h4>Description</h4>
            <p class="lead">@course.Description</p>

            <h4>Schedule &amp; Location</h4>
            <table class="table table-bordered w-auto">
                <tr>
                    <th>Schedule</th>
                    <td>@course.Schedule</td>
                </tr>
                <tr>
                    <th>Location</th>
                    <td>@course.Location</td>
                </tr>
                <tr>
                    <th>Enrollment</th>
                    <td>@course.CurrentEnrollment / @course.MaxEnrollment students</td>
                </tr>
            </table>

            <div class="mt-4">
                <a href="@($"enroll?courseId={course.Id}")" class="btn btn-primary btn-lg">Request Enrollment</a>
                <a href="courses" class="btn btn-outline-secondary btn-lg ms-2">Back to Catalog</a>
            </div>
        </div>

        <div class="col-lg-4">
            @if (instructor is not null)
            {
                <div class="card shadow-sm">
                    <div class="card-header bg-dark text-white">
                        <h5 class="mb-0">👨‍🏫 Instructor</h5>
                    </div>
                    <div class="card-body">
                        <h5>@instructor.Name</h5>
                        <p class="text-muted mb-2">@instructor.Title</p>
                        <p class="mb-2">
                            <a href="mailto:@instructor.Email">@instructor.Email</a>
                        </p>
                        <hr />
                        <p>@instructor.Bio</p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive confirmation from the registrar's office.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>
            Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been submitted.
        </p>
        <hr />
        <p class="mb-0">The registrar's office will process your request and contact you at <strong>@Model.Email</strong>.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., STU123456" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address</label>
                    <InputText id="email" class="form-control" @bind-Value="Model.Email" placeholder="you@university.edu" />
                    <ValidationMessage For="() => Model.Email" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" class="form-control" @bind-Value="Model.Comments" rows="3"
                                   placeholder="Any special requests or notes for the registrar…" />
                </div>

                <button type="submit" class="btn btn-primary btn-lg">Submit Request</button>
            </EditForm>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">ℹ️ Enrollment Info</h5>
                    <ul class="mb-0">
                        <li>Requests are typically processed within 2 business days.</li>
                        <li>You will receive a confirmation email once approved.</li>
                        <li>Contact the registrar at <strong>registrar@university.edu</strong> for questions.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>
<p>Search and filter to find the right courses for you.</p>

<div class="row mb-4 g-3">
    <div class="col-md-5">
        <input type="text" class="form-control" placeholder="Search by title, code, or keyword…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <select class="form-select" @bind="selectedCredits">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted">Showing @filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    var dept = CatalogService.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td><small>@course.Schedule</small></td>
                        <td>
                            @if (spotsLeft <= 5)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-success">@spotsLeft spots left</span>
                            }
                        </td>
                        <td>
                            <a href="@($"courses/{course.Id}")" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;
    private int _selectedCredits;

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    private int selectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.SearchCourses(
            _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null,
            _selectedCredits > 0 ? _selectedCredits : null);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course Not Found</h4>
        <p>The course you're looking for doesn't exist. <a href="courses">Browse all courses</a>.</p>
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code: @course.Title</h1>
            <div class="mb-3">
                <span class="badge bg-primary fs-6">@department?.Name</span>
                <span class="badge bg-secondary fs-6">@course.Credits Credits</span>
                @{
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                }
                @if (spotsLeft <= 5)
                {
                    <span class="badge bg-warning text-dark fs-6">@spotsLeft spots remaining</span>
                }
                else
                {
                    <span class="badge bg-success fs-6">@spotsLeft spots remaining</span>
                }
            </div>

            <h4>Description</h4>
            <p class="lead">@course.Description</p>

            <h4>Schedule &amp; Location</h4>
            <table class="table table-bordered w-auto">
                <tr>
                    <th>Schedule</th>
                    <td>@course.Schedule</td>
                </tr>
                <tr>
                    <th>Location</th>
                    <td>@course.Location</td>
                </tr>
                <tr>
                    <th>Enrollment</th>
                    <td>@course.CurrentEnrollment / @course.MaxEnrollment students</td>
                </tr>
            </table>

            <div class="mt-4">
                <a href="@($"enroll?courseId={course.Id}")" class="btn btn-primary btn-lg">Request Enrollment</a>
                <a href="courses" class="btn btn-outline-secondary btn-lg ms-2">Back to Catalog</a>
            </div>
        </div>

        <div class="col-lg-4">
            @if (instructor is not null)
            {
                <div class="card shadow-sm">
                    <div class="card-header bg-dark text-white">
                        <h5 class="mb-0">👨‍🏫 Instructor</h5>
                    </div>
                    <div class="card-body">
                        <h5>@instructor.Name</h5>
                        <p class="text-muted mb-2">@instructor.Title</p>
                        <p class="mb-2">
                            <a href="mailto:@instructor.Email">@instructor.Email</a>
                        </p>
                        <hr />
                        <p>@instructor.Bio</p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive confirmation from the registrar's office.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>
            Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been submitted.
        </p>
        <hr />
        <p class="mb-0">The registrar's office will process your request and contact you at <strong>@Model.Email</strong>.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., STU123456" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address</label>
                    <InputText id="email" class="form-control" @bind-Value="Model.Email" placeholder="you@university.edu" />
                    <ValidationMessage For="() => Model.Email" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" class="form-control" @bind-Value="Model.Comments" rows="3"
                                   placeholder="Any special requests or notes for the registrar…" />
                </div>

                <button type="submit" class="btn btn-primary btn-lg">Submit Request</button>
            </EditForm>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">ℹ️ Enrollment Info</h5>
                    <ul class="mb-0">
                        <li>Requests are typically processed within 2 business days.</li>
                        <li>You will receive a confirmation email once approved.</li>
                        <li>Contact the registrar at <strong>registrar@university.edu</strong> for questions.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

